CREATE TRIGGER `doc_access_tokens_bound_insert` BEFORE INSERT ON `doc_access_tokens` WHEN NEW.contact_id IS NULL OR NEW.client_id IS NULL OR NEW.email IS NULL OR NEW.email <> lower(NEW.email) OR NOT EXISTS (SELECT 1 FROM documents d WHERE d.id = NEW.document_id AND d.client_id = NEW.client_id AND d.frozen_at IS NOT NULL) OR NOT EXISTS (SELECT 1 FROM contacts c WHERE c.id = NEW.contact_id AND c.client_id = NEW.client_id) OR (NEW.send_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM document_sends s WHERE s.id = NEW.send_id AND s.document_id = NEW.document_id AND s.contact_id = NEW.contact_id)) BEGIN SELECT RAISE(ABORT, 'doc_access_tokens_bound_insert: an invoice link belongs to one contact of the client of a frozen document, with the address in lower case'); END;
