CREATE TRIGGER `reminders_fixed` BEFORE UPDATE ON `reminders` WHEN NEW.`document_id` IS NOT OLD.`document_id` OR NEW.`offset_days` IS NOT OLD.`offset_days` OR NEW.`due_at` IS NOT OLD.`due_at` OR (OLD.sent_at IS NOT NULL AND NEW.sent_at IS NOT OLD.sent_at AND NOT (NEW.sent_at IS NULL AND OLD.email_log_id IS NULL)) OR (OLD.email_log_id IS NOT NULL AND NEW.email_log_id IS NOT OLD.email_log_id) OR (NEW.skipped_reason IS NOT OLD.skipped_reason AND NOT ((OLD.skipped_reason IS NULL AND NEW.skipped_reason IS NOT NULL) OR (OLD.skipped_reason IS 'paused' AND NEW.skipped_reason IS NULL))) BEGIN SELECT RAISE(ABORT, 'reminders_fixed: a reminder keeps its document, offset and due time, is sent once, and is paused or skipped only by the allowed moves'); END;
